"""One-time Nifty Indices constituent snapshot (12 September 2026).

Stocks come from the official public Index Constituent CSV for each listed
Nifty sectoral index.  ETF symbols are deliberately conservative: a missing
ETF is represented by an empty list and the UI reports it as unavailable.
"""

def symbols(value: str) -> list[str]:
    return [f"{symbol}.NS" for symbol in value.split()]


